INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("フリーマーケット会場", "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 10118, 40, 7, 1, "ペコリーヌとの出会い", 2834, 5118061, 20063115, "青空の下で謁見", 2, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("フリーマーケット会場", "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 10118, 40, 7, 1, "マホとの出会い", 2835, 5118062, 20063115, "未来の騎空団\nマスコット？", 2, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("ランドソル市街地", "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 10118, 40, 7, 1, "アキノとの出会い", 2837, 5118063, 20063115, "お嬢さまからの\n緊急依頼", 2, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("フリーマーケット会場", "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 10118, 40, 18, 1, "ジュンとの出会い", 4108402, 5118064, 20063115, "黄金色の悩みごと", 2, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("フリーマーケット会場", "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 10118, 40, 18, 1, "カオリとの出会い", 4107402, 5118065, 20063115, "白熱！　格闘大会！", 2, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("オーエド町", "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 10118, 40, 16, 1, "ニノンとの出会い", 9000227, 5118066, 20063115, "祭り太鼓はオーエドの華", 2, 8, 1, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("フリーマーケット会場", "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 10118, 40, 19, 1, "スズナとの出会い", 2101181, 5118067, 20063115, "人気者は遅れて\nやってくる", 3, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("ランドソル市街地", "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 10118, 40, 18, 1, "ナナカとの出会い", 4109402, 5118068, 20063115, "巫女・ミーツ・魔法少女", 3, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("フリーマーケット会場", "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 10118, 40, 18, 1, "キャル＆コッコロとの出会い", 4305402, 5118069, 20063115, "ネズ耳は二度なくなる", 3, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("ランドソル市街地", "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 10118, 40, 18, 1, "ユカリとの出会い", 4101402, 5118070, 20063115, "この出会いにカンパイ！", 3, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("ランドソル市街地", "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 10118, 40, 18, 1, "アオイとの出会い", 4106402, 5118071, 20063115, "陰陽アンサンブル", 3, 8, 0, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES ("フリーマーケット会場", "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 10118, 40, 7, 1, "シノブとの出会い", 2836, 5118072, 20063115, "運試し十番勝負！", 3, 8, 1, 91002);
INSERT INTO `v1_318f00d34af7d5e1a24ae7fc018b5da77c216034ddc147766b6d61bdc0105935` VALUES (0, 0, 10118, 0, 0, 0, "オープニング", 0, 5118600, 20063115, "彼女たちの新たな日常", 1, 0, 0, 0);
